from __future__ import annotations

import asyncio
import gzip
import hashlib
import json
from collections.abc import Mapping
from pathlib import Path
from threading import Event
from time import monotonic, sleep
from typing import cast
from urllib.parse import urlparse

import httpx
from sqlalchemy import create_engine, inspect
from sqlalchemy.engine import Engine
from zhixing_jobs import (
    JOB_EXECUTION_TOKEN_HEADER,
    WORKER_ID_HEADER,
    JobExecutionContext,
    JobRecord,
    JobRepository,
    PermanentJobError,
    RetryableJobError,
    WorkerRunner,
)
from zhixing_jobs.runner import JobHandler
from zhixing_observability import REQUEST_ID_HEADER, RUN_ID_HEADER

from zhixing_worker.config import WorkerSettings, load_settings
from zhixing_worker.sync_store import SyncStore


def noop_handler(
    job: JobRecord,
    context: JobExecutionContext,
) -> Mapping[str, object]:
    context.ensure_active()
    return {"accepted": True, "job_id": job.id}


def _execute_lingxing_sync(
    job: JobRecord,
    context: JobExecutionContext,
    settings: WorkerSettings,
    *,
    transport: httpx.AsyncBaseTransport | None = None,
) -> Mapping[str, object]:
    """Execute one bounded read-only page and archive the response.

    The API only enqueues this job; all external I/O happens here.
    """
    context.ensure_active()
    if job.payload.get("provider") != "lingxing":
        raise PermanentJobError("同步任务来源不受支持", code="sync.provider_unsupported")
    resource = str(job.payload.get("resource_key") or "")
    path = {
        "shops": "/erp/sc/data/amazon/shop/list",
        "products": "/erp/sc/data/product/list",
        # Legacy alias remains accepted for already queued jobs.
        "catalog.shop": "/erp/sc/data/amazon/shop/list",
        "orders": "/erp/sc/data/amazon/order",
        "inventory": "/erp/sc/data/inventory/list",
    }.get(resource)
    if path is None:
        raise PermanentJobError("同步资源未进入只读目录", code="sync.resource_unsupported")
    if not settings.lingxing_app_id or not settings.lingxing_app_secret:
        raise PermanentJobError("领星凭据未配置", code="sync.credentials_missing")
    if urlparse(settings.lingxing_base_url).hostname != "openapi.lingxing.com":
        raise PermanentJobError("领星 Host 不在官方只读 allowlist", code="sync.host_blocked")

    async def fetch_page(page: int) -> dict[str, object]:
        async with httpx.AsyncClient(
            base_url=settings.lingxing_base_url,
            timeout=60,
            transport=transport,
        ) as client:
            response = await client.get(path, params={"page": str(page)})
            if response.status_code == 429 or response.status_code >= 500:
                raise RetryableJobError("领星暂时不可用", code="sync.external_retryable")
            response.raise_for_status()
            value = response.json()
            return value if isinstance(value, dict) else {"data": value}

    start_page = max(1, int(str(job.payload.get("checkpoint", job.payload.get("page", 1)))))
    pages: list[dict[str, object]] = []
    page = start_page
    while True:
        payload = asyncio.run(fetch_page(page))
        pages.append({"page": page, "payload": payload})
        data = payload.get("data")
        has_more = isinstance(data, dict) and bool(data.get("has_more", False))
        if not has_more:
            break
        page += 1
        if page - start_page >= 1000:
            raise PermanentJobError("领星分页超过安全上限", code="sync.pagination_limit")
    archive_root = Path(
        settings.source_archive_path or Path.cwd() / "var" / "source-archive"
    ).resolve()
    archived_pages: list[dict[str, object]] = []
    for page_item in pages:
        page_payload = page_item["payload"]
        raw = json.dumps(page_payload, ensure_ascii=False, separators=(",", ":")).encode()
        digest = hashlib.sha256(raw).hexdigest()
        target = archive_root / digest[:2] / f"{digest}.json.gz"
        target.parent.mkdir(parents=True, exist_ok=True)
        temp = target.with_suffix(".tmp")
        with gzip.open(temp, "wb") as stream:
            stream.write(raw)
        temp.replace(target)
        archived_pages.append(
            {
                "page": page_item["page"],
                "content_hash": digest,
                "storage_key": str(target.relative_to(archive_root)),
                "byte_count": len(raw),
                "row_count": _raw_row_count(cast(Mapping[str, object], page_payload)),
                "cursor": str(page_item["page"]),
            }
        )
    context.ensure_active()
    last = archived_pages[-1]
    return {
        "provider": "lingxing",
        "resource_key": resource,
        "content_hash": last["content_hash"],
        "storage_key": last["storage_key"],
        "byte_count": last["byte_count"],
        "row_count": sum(_result_int(item["row_count"]) for item in archived_pages),
        "cursor": str(last["cursor"]),
        "pages": archived_pages,
    }


def lingxing_sync_handler(job: JobRecord, context: JobExecutionContext) -> Mapping[str, object]:
    return _execute_lingxing_sync(job, context, load_settings())


def _raw_row_count(payload: Mapping[str, object]) -> int:
    data = payload.get("data")
    if isinstance(data, list):
        return len(data)
    if isinstance(data, dict):
        for key in ("list", "items", "records"):
            value = data.get(key)
            if isinstance(value, list):
                return len(value)
    return 0


def _result_int(value: object) -> int:
    if isinstance(value, int):
        return value
    raise PermanentJobError("同步结果计数无效", code="sync.result_invalid")


def build_lingxing_sync_handler(
    settings: WorkerSettings,
    engine: Engine,
    *,
    transport: httpx.AsyncBaseTransport | None = None,
) -> JobHandler:
    store = SyncStore(engine)

    def handler(job: JobRecord, context: JobExecutionContext) -> Mapping[str, object]:
        source_key = str(job.payload.get("source_id") or "")
        resource_key = str(job.payload.get("resource_key") or "")
        partition = str(job.payload.get("partition") or "default")
        try:
            ref = store.begin_resource(
                sync_run_id=job.run_id,
                source_key=source_key,
                resource_key=resource_key,
                partition=partition,
                enterprise_id=job.enterprise_id,
            )
        except LookupError as exc:
            raise PermanentJobError(
                "同步资源未登记或已停用", code="sync.resource_not_registered"
            ) from exc
        try:
            result = _execute_lingxing_sync(
                job,
                context,
                settings,
                transport=transport,
            )
        except Exception:
            store.finish_resource(ref.run_id, status="failed")
            raise
        page_results = result.get("pages")
        if not isinstance(page_results, list):
            page_results = [result]
        for page_result in page_results:
            if not isinstance(page_result, dict):
                raise PermanentJobError("同步页结果无效", code="sync.result_invalid")
            store.record_page(
                ref,
                partition=partition,
                cursor=str(page_result["cursor"]),
                storage_key=str(page_result["storage_key"]),
                content_hash=str(page_result["content_hash"]),
                byte_count=_result_int(page_result["byte_count"]),
                row_count=_result_int(page_result["row_count"]),
                page_number=_result_int(page_result["page"]),
            )
        store.finish_resource(ref.run_id)
        return result

    return handler


def build_analysis_review_handler(
    settings: WorkerSettings,
    *,
    transport: httpx.BaseTransport | None = None,
) -> JobHandler:
    def handler(job: JobRecord, context: JobExecutionContext) -> Mapping[str, object]:
        context.ensure_active()
        if not job.execution_token:
            raise PermanentJobError(
                "巡店任务缺少当前 Worker 领取令牌",
                code="authorization.worker_execution_token_missing",
            )
        try:
            with httpx.Client(
                base_url=settings.api_base_url,
                timeout=settings.api_timeout_seconds,
                transport=transport,
            ) as client:
                response = client.post(
                    f"/api/v1/analysis/internal/jobs/{job.id}/execute",
                    headers={
                        REQUEST_ID_HEADER: job.request_id,
                        RUN_ID_HEADER: job.run_id,
                        WORKER_ID_HEADER: settings.worker_id,
                        JOB_EXECUTION_TOKEN_HEADER: job.execution_token,
                    },
                )
        except httpx.HTTPError as exc:
            raise RetryableJobError(
                f"巡店 API 暂不可用：{exc}",
                code="analysis.schedule.api_unavailable",
            ) from exc
        context.ensure_active()
        if response.status_code >= 500:
            raise RetryableJobError(
                "巡店 API 返回服务端错误",
                code="analysis.schedule.api_server_error",
            )
        if response.status_code >= 400:
            raise PermanentJobError(
                _api_error_message(response),
                code=_api_error_code(response),
            )
        payload = response.json()
        if not isinstance(payload, dict):
            raise PermanentJobError(
                "巡店 API 返回了无效响应",
                code="analysis.schedule.api_invalid_response",
            )
        return {str(key): value for key, value in payload.items()}

    return handler


def _api_error_code(response: httpx.Response) -> str:
    try:
        payload = response.json()
    except ValueError:
        return "analysis.schedule.api_rejected"
    if isinstance(payload, dict):
        error = payload.get("error")
        if isinstance(error, dict) and isinstance(error.get("code"), str):
            return str(error["code"])
    return "analysis.schedule.api_rejected"


def _api_error_message(response: httpx.Response) -> str:
    try:
        payload = response.json()
    except ValueError:
        return f"巡店 API 拒绝任务（HTTP {response.status_code}）"
    if isinstance(payload, dict):
        error = payload.get("error")
        if isinstance(error, dict) and isinstance(error.get("message"), str):
            return str(error["message"])
    return f"巡店 API 拒绝任务（HTTP {response.status_code}）"


def create_worker_engine(settings: WorkerSettings) -> Engine:
    connect_args = (
        {"check_same_thread": False} if settings.database_url.startswith("sqlite") else {}
    )
    pool_options: dict[str, int | float] = {}
    if not settings.database_url.startswith("sqlite"):
        pool_options = {
            "pool_size": settings.database_pool_size,
            "max_overflow": settings.database_max_overflow,
            "pool_timeout": settings.database_pool_timeout_seconds,
            "pool_recycle": settings.database_pool_recycle_seconds,
        }
    return create_engine(
        settings.database_url,
        pool_pre_ping=True,
        connect_args=connect_args,
        **pool_options,
    )


def wait_for_schema(engine: Engine, timeout_seconds: float) -> None:
    deadline = monotonic() + timeout_seconds
    while True:
        try:
            if inspect(engine).has_table("background_jobs"):
                return
        except Exception:
            pass
        if monotonic() >= deadline:
            raise RuntimeError("后台任务表尚未就绪；请确认数据库可访问并先执行 pnpm db:upgrade")
        sleep(0.2)


def build_runner(settings: WorkerSettings, engine: Engine) -> WorkerRunner:
    return WorkerRunner(
        JobRepository(engine),
        {
            "system.noop": noop_handler,
            "data-source.sync": build_lingxing_sync_handler(settings, engine),
            "analysis.daily-store-review": build_analysis_review_handler(settings),
        },
        worker_id=settings.worker_id,
        poll_seconds=settings.poll_seconds,
        lease_seconds=settings.lease_seconds,
        retry_delay_seconds=settings.retry_delay_seconds,
    )


def run(*, once: bool = False, stop_event: Event | None = None) -> int:
    settings = load_settings()
    engine = create_worker_engine(settings)
    try:
        wait_for_schema(engine, settings.schema_wait_seconds)
        runner = build_runner(settings, engine)
        if once:
            runner.run_once()
            return 0
        runner.run_forever(stop_event or Event())
        return 0
    finally:
        engine.dispose()

from __future__ import annotations

from dataclasses import dataclass
from uuid import uuid4

from sqlalchemy import Engine, inspect, text


@dataclass(frozen=True, slots=True)
class ResourceRunRef:
    resource_id: str
    run_id: str


class SyncStore:
    """Small Worker-owned persistence boundary for the 0054 ingestion ledger."""

    def __init__(self, engine: Engine) -> None:
        self.engine = engine

    def _has_column(self, table: str, column: str) -> bool:
        if self.engine.url.database == ":memory:":
            return False
        return column in {item["name"] for item in inspect(self.engine).get_columns(table)}

    def _has_table(self, table: str) -> bool:
        if self.engine.url.database == ":memory:":
            return False
        return inspect(self.engine).has_table(table)

    def begin_resource(
        self,
        *,
        sync_run_id: str,
        source_key: str,
        resource_key: str,
        partition: str,
        enterprise_id: str | None = None,
    ) -> ResourceRunRef:
        with self.engine.begin() as connection:
            enterprise_clause = (
                " AND es.enterprise_id = :enterprise_id"
                if enterprise_id is not None
                and self._has_column("external_systems", "enterprise_id")
                else ""
            )
            resource_id = connection.execute(
                text(
                    "SELECT sr.id FROM source_resources sr "
                    "JOIN external_systems es ON es.id = sr.external_system_id "
                    "WHERE es.system_key = :source_key AND sr.resource_key = :resource_key "
                    "AND sr.enabled = true" + enterprise_clause
                ),
                {
                    "source_key": source_key,
                    "resource_key": resource_key,
                    "enterprise_id": enterprise_id,
                },
            ).scalar_one_or_none()
            if resource_id is None:
                raise LookupError("source resource is missing or disabled")
            existing = connection.execute(
                text(
                    "SELECT id FROM sync_resource_runs WHERE sync_run_id = :sync_run_id "
                    "AND source_resource_id = :resource_id AND partition_key = :partition"
                ),
                {
                    "sync_run_id": sync_run_id,
                    "resource_id": resource_id,
                    "partition": partition,
                },
            ).scalar_one_or_none()
            run_id = str(existing or f"sync_resource_run_{uuid4().hex}")
            if existing is None:
                if self._has_column("sync_resource_runs", "started_at"):
                    connection.execute(
                        text(
                            "INSERT INTO sync_resource_runs "
                            "(id, sync_run_id, source_resource_id, status, partition_key, "
                            "records_read, records_written, started_at) VALUES "
                            "(:id, :sync_run_id, :resource_id, 'running', :partition, "
                            "0, 0, CURRENT_TIMESTAMP)"
                        ),
                        {
                            "id": run_id,
                            "sync_run_id": sync_run_id,
                            "resource_id": resource_id,
                            "partition": partition,
                        },
                    )
                else:
                    connection.execute(
                        text(
                            "INSERT INTO sync_resource_runs "
                            "(id, sync_run_id, source_resource_id, status, partition_key, "
                            "records_read, records_written) VALUES "
                            "(:id, :sync_run_id, :resource_id, 'running', :partition, 0, 0)"
                        ),
                        {
                            "id": run_id,
                            "sync_run_id": sync_run_id,
                            "resource_id": resource_id,
                            "partition": partition,
                        },
                    )
            return ResourceRunRef(resource_id=str(resource_id), run_id=run_id)

    def record_page(
        self,
        ref: ResourceRunRef,
        *,
        partition: str,
        cursor: str,
        storage_key: str,
        content_hash: str,
        byte_count: int,
        row_count: int,
        page_number: int | None = None,
        schema_status: str = "unknown",
    ) -> bool:
        """Persist one page once and advance its checkpoint transactionally."""
        with self.engine.begin() as connection:
            exists = connection.execute(
                text("SELECT id FROM raw_page_manifests WHERE content_hash = :digest"),
                {"digest": content_hash},
            ).scalar_one_or_none()
