    def finish_resource(self, run_id: str, *, status: str = "succeeded") -> None:
        with self.engine.begin() as connection:
            connection.execute(
                text("UPDATE sync_resource_runs SET status = :status WHERE id = :id"),
                {"status": status, "id": run_id},
